export function getLogo(name: string): Logo | undefined {
  return LOGOS[name.toLowerCase()];
}

/** The file to show for the theme; falls back to the light one. */
export function getLogoUrl(name: string, theme: LogoTheme = 'light'): string | undefined {
  const logo = getLogo(name);
  if (!logo) {
    return undefined;
  }
  return theme === 'dark' ? (logo.dark ?? logo.light) : logo.light;
}
